<script setup lang="ts">
import {pmsFetch, pmsLoading, withoutPmsLoader} from './loading';
import PmsAccountMenu from './PmsAccountMenu.vue';
import PmsTeamNavigation from './PmsTeamNavigation.vue';
import PmsFormDialog from './PmsFormDialog.vue';
import PmsTableControls from './PmsTableControls.vue';
import './pms-source.css';
import './pms-layout.css';
import './pms-reference-pages.css';
import './pms-alignment.css';
import './pms-icons.css';
import './pms-form-controls.css';

import PmsPermissions from './PmsPermissions.vue';
import PmsProfile from './PmsProfile.vue';
import PmsNotifications from './PmsNotifications.vue';
import PmsInvitations from './PmsInvitations.vue';
import PmsTeamSpace from './PmsTeamSpace.vue';
import PmsDashboard from './PmsDashboard.vue';
import PmsReports from './PmsReports.vue';
import PmsWorkLogs from './PmsWorkLogs.vue';
import PmsTeamActivity from './PmsTeamActivity.vue';
import PmsMyWork from './PmsMyWork.vue';
import PmsWorkflows from './PmsWorkflows.vue';
import PmsEmployees from './PmsEmployees.vue';
import PmsProjects from './PmsProjects.vue';
import {subscribePmsUpdates} from './realtime';
import {ref,onMounted,onUnmounted,computed} from 'vue';
let disconnectUpdates:(()=>void)|undefined,heartbeat:ReturnType<typeof setInterval>|undefined;onUnmounted(()=>{disconnectUpdates?.();if(heartbeat)clearInterval(heartbeat);});const userId=ref<number|null>(null),profileOpen=ref(false);
const props=defineProps<{csrf?:string;theme?:'light'|'dark'}>();
const selectedDepartment=ref<number|null>(null),selectedProject=ref<number|null>(null),createDepartment=ref<number|null>(null),navigationVersion=ref(0),pendingInvitations=ref(0);function teamUrl(sectionName:string,values:Record<string,string>={}){const url=new URL(location.href);for(const key of ['project','department','issue','workflow','sprint','assignee','status','source'])url.searchParams.delete(key);url.searchParams.set('section',sectionName);for(const [key,value]of Object.entries(values))url.searchParams.set(key,value);history.replaceState(null,'',url);error.value='';message.value='';}
function teamDepartment(id:number){teamUrl('team-space',{department:String(id)});selectedDepartment.value=id;selectedProject.value=null;createDepartment.value=null;section.value='team-space';navigationVersion.value++;}
function teamProject(id:number){teamUrl('project-board',{project:String(id),source:'team-space'});selectedProject.value=id;selectedDepartment.value=null;createDepartment.value=null;section.value='projects';navigationVersion.value++;}
function teamCreate(id:number){teamUrl('projects');createDepartment.value=id;selectedProject.value=null;selectedDepartment.value=null;section.value='projects';navigationVersion.value++;}

const rolePreview=ref<any>(null),permissionSearch=ref('');const visiblePermissions=computed(()=>catalog.value.filter(p=>(p.permission_name+' '+p.permission_key).toLowerCase().includes(permissionSearch.value.toLowerCase())));
const initializing=ref(true);const accountName=ref('');const branding=ref<any>({});const permissions=ref<string[]>([]),section=ref('projects'),rows=ref<any[]>([]),catalog=ref<any[]>([]),editor=ref<any>(null),busy=ref(false),loading=ref(false),error=ref(''),message=ref('');
const permitted=(key:string)=>permissions.value.includes('*')||permissions.value.includes(key);
if(['employees'].includes(new URLSearchParams(location.search).get('section')||'')||(window.portal.admin&&new URLSearchParams(location.search).get('section')==='invitations'))window.location.replace('/admin#'+(new URLSearchParams(location.search).get('section')==='invitations'?'invitations':new URLSearchParams(location.search).get('section')==='roles'||new URLSearchParams(location.search).get('section')==='permissions'?'roles':'users'));
const navigation=[{id:'roles',label:'Roles & permissions',permission:'role-view',icon:'shield-lock'},{id:'system-health',label:'System Health',permission:'pulse-view',icon:'heartbeat'},{id:'dashboard',label:'Dashboard',permission:'dashboard-view',icon:'layout-dashboard'},{id:'my-work',label:'My Work',permission:'my-work-view',icon:'layout-kanban'},{id:'projects',label:'Projects',permission:'project-view',icon:'folders'},{id:'team-space',label:'Team Space',permission:'project-view',icon:'users'},{id:'work-logs',label:'Work Logs',permission:'summary-view',icon:'history'},{id:'departments',label:'Departments',permission:'department-view',icon:'building'},{id:'workflows',label:'Workflows',permission:'department-view',icon:'route'},{id:'reports',label:'Reports',permission:'report-view',icon:'chart-bar'},{id:'team-activity',label:'Team Activity',permission:'time-tracking-dashboard',icon:'activity'}];
navigation.sort((a,b)=>['dashboard','my-work','projects','team-space','work-logs','messages','invitations','employees','departments','workflows','roles','permissions','reports','team-activity','system-health','settings-mail','settings-branding','settings-realtime'].indexOf(a.id)-['dashboard','my-work','projects','team-space','work-logs','messages','invitations','employees','departments','workflows','roles','permissions','reports','team-activity','system-health','settings-mail','settings-branding','settings-realtime'].indexOf(b.id));
const adminIds=['permissions','employees','departments','workflows','roles','reports','team-activity','system-health','settings-mail','settings-branding','settings-realtime'];const navGroups=[{label:'Workspace',items:navigation.filter(i=>!adminIds.includes(i.id))},{label:'Administration',items:navigation.filter(i=>adminIds.includes(i.id))}];
const tablePage=ref(1),tableSize=ref(10),tableSearch=ref('');const filteredRows=computed(()=>rows.value.filter(row=>Object.values(row).filter(v=>typeof v==='string').join(' ').toLowerCase().includes(tableSearch.value.toLowerCase())));const pagedRows=computed(()=>tableSize.value<0?filteredRows.value:filteredRows.value.slice((tablePage.value-1)*tableSize.value,tablePage.value*tableSize.value));
const key=computed(()=>section.value==='departments'?'department':'role');
async function request(path:string,method='GET',body?:any){const r=await pmsFetch('/pms/api/'+path,{method,headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:body?JSON.stringify(body):undefined});const json=await r.json();if(!r.ok)throw Error(Object.values(json.errors||{}).flat().join(' ')||json.message||'Unable to complete this action.');return json;}
async function load(){loading.value=true;error.value='';try{const data=await request(section.value);rows.value=data.data;catalog.value=data.permissions||[];}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
async function change(s:string){const url=new URL(location.href);url.searchParams.delete('project');url.searchParams.delete('department');url.searchParams.delete('issue');for(const key of ['workflow','sprint','assignee','status'])url.searchParams.delete(key);url.searchParams.set('section',s);history.replaceState(null,'',url);if(s==='projects'){selectedProject.value=null;createDepartment.value=null;navigationVersion.value++;}section.value=s;error.value='';tablePage.value=1;tableSearch.value='';editor.value=null;message.value='';if(s==='system-health'){window.location.assign('/pms/system-health');return;}if(!s.startsWith('settings-')&&!['permissions','messages','invitations','team-space','dashboard','reports','work-logs','team-activity','my-work','projects','employees','workflows'].includes(s))await load();}
function edit(row?:any){permissionSearch.value='';editor.value=row?{...row,permission_ids:row.permissions?.map((p:any)=>p.id)||[]}:(section.value==='departments'?{dept_name:'',description:'',status:1}:{role_name:'',role_key:'',permission_ids:[]});}
async function save(){busy.value=true;error.value='';try{const result=await request(section.value+(editor.value.id?'/'+editor.value.id:''),'POST',editor.value);message.value=result.message;editor.value=null;await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function remove(row:any){if(!confirm('Permanently delete '+(row.dept_name||row.role_name)+'?'))return;busy.value=true;try{const result=await request(section.value+'/'+row.id,'DELETE');message.value=result.message;await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(async()=>{if('serviceWorker' in navigator&&window.isSecureContext)void navigator.serviceWorker.register('/pms/service-worker.js',{scope:'/pms'}).catch(()=>{});let manifest=document.querySelector('link[rel=manifest]');if(!manifest){manifest=document.createElement('link');manifest.setAttribute('rel','manifest');manifest.setAttribute('href','/pms-assets/manifest.webmanifest');document.head.appendChild(manifest);}try{const meta=window.portal.pmsBootstrap||await request('');permissions.value=meta.permissions;branding.value=meta.branding||{};userId.value=meta.user_id;accountName.value=meta.user?.name||meta.name||'';if(meta.user_id)heartbeat=setInterval(()=>{if(!document.hidden)withoutPmsLoader(()=>void request('').catch(()=>{}));},60000);section.value=permitted('dashboard-view')?'dashboard':permitted('project-view')?'projects':permitted('my-work-view')?'my-work':permitted('department-view')?'departments':'roles';const query=new URLSearchParams(window.location.search);const explicitSection=query.get('section');selectedDepartment.value=Number(query.get('department'))||null;if(query.get('source')==='team-space')selectedProject.value=Number(query.get('project'))||null;if(explicitSection==='projects'){const url=new URL(location.href);url.searchParams.delete('project');url.searchParams.delete('issue');history.replaceState(null,'',url);}const requested=explicitSection==='project-board'?'projects':explicitSection||(query.has('department')?'team-space':query.has('project')?'projects':null);const item=navigation.find(i=>i.id===requested&&permitted(i.permission));if(item)section.value=item.id;if(['departments','roles'].includes(section.value)&&permitted(key.value+'-view'))await load();initializing.value=false;disconnectUpdates=await subscribePmsUpdates(String(meta.user_id||'super'),props.csrf||'',event=>withoutPmsLoader(()=>window.dispatchEvent(new CustomEvent('pms:changed',{detail:event}))));}catch(e){error.value=(e as Error).message;}finally{initializing.value=false;}});
</script>
<template><section class="pms-workspace" :class="{'pms-dark':props.theme==='dark'}"><div v-if="pmsLoading||initializing" class="pms-global-loader" role="status" aria-live="polite" aria-label="Loading PMS"><div class="pms-global-loader-card"><span class="pms-loading-spinner" aria-hidden="true"></span><span>Please wait...</span></div></div><aside class="pms-sidebar"><a class="pms-brand" href="/products"><img v-if="branding.sidebar_logo" :src="'/storage/'+branding.sidebar_logo" alt="PMS" style="width:32px;height:32px;object-fit:contain"><span v-else>J</span><img v-if="branding.sidebar_logo_text" :src="'/storage/'+(props.theme==='dark'&&branding.sidebar_logo_text_dark?branding.sidebar_logo_text_dark:branding.sidebar_logo_text)" alt="PMS" style="max-width:150px;max-height:36px;object-fit:contain"><strong v-else>Judibas PMS</strong></a><div class="pms-menu-scroll"><template v-for="group in navGroups" :key="group.label"><p v-if="group.items.some(i=>permitted(i.permission))" class="menu-header">{{group.label}}</p><nav class="admin-tabs" :aria-label="group.label"><template v-for="item in group.items.filter(i=>permitted(i.permission))" :key="item.id"><PmsTeamNavigation v-if="item.id==='team-space'" :department-id="selectedDepartment" :project-id="selectedProject" :active="section==='team-space'||(section==='projects'&&(!!selectedProject))" :permissions="permissions" @department="teamDepartment" @project="teamProject" @create="teamCreate"/><button v-else :class="{active:section===item.id}" @click="change(item.id)"><i aria-hidden="true" class="ti" :class="'ti-'+item.icon"></i>{{item.label}}<span v-if="item.id==='invitations'&&pendingInvitations" class="badge bg-primary rounded-pill ms-auto">{{pendingInvitations}}</span></button></template></nav></template><a class="pms-products-link" href="/products">&larr; All products</a></div></aside><div class="pms-page"><header class="pms-topbar"><span class="pms-navbar-spacer"></span><div class="pms-topbar-actions"><PmsNotifications :csrf="csrf"/><PmsAccountMenu :name="accountName||'Super Admin'" :csrf="csrf" :can-edit="!!userId" :super-admin="permissions.includes('*')" @profile="profileOpen=true"/></div></header><main class="pms-content"><PmsFormDialog v-if="rolePreview" :title="rolePreview.role_name+' permissions'" subtitle="Permissions assigned to this PMS role." centered @close="rolePreview=null"><div class="pms-role-permission-preview"><span v-for="p in rolePreview.permissions" :key="p.id"><i class="ti ti-check" aria-hidden="true"></i>{{p.permission_name}}</span><p v-if="!rolePreview.permissions?.length" class="muted">No permissions assigned.</p></div><template #footer><button class="button" @click="rolePreview=null">Close</button></template></PmsFormDialog><PmsProfile v-if="profileOpen" :csrf="csrf" @close="profileOpen=false"/><p v-if="error" class="notice admin-error" role="alert">{{error}}</p><p v-if="message" class="notice" role="status">{{message}}</p><template v-if="initializing" class="muted" role="status"></template><template v-else><PmsPermissions v-if="section==='permissions'&&permitted('permission-view')" :csrf="csrf" :permissions="permissions"/><p v-else-if="section.startsWith('settings-')">Settings are managed in Judibas Administration.</p><PmsDashboard :name="accountName" v-else-if="section==='dashboard'&&permitted('dashboard-view')"/><PmsInvitations @changed="pendingInvitations=$event" v-else-if="section==='invitations'" :csrf="csrf"/><PmsTeamSpace :key="'department-'+navigationVersion" :initial-department="selectedDepartment" @create-project="teamCreate" v-else-if="section==='team-space'&&permitted('project-view')" :csrf="csrf" :permissions="permissions"/><PmsReports v-else-if="section==='reports'&&permitted('report-view')"/><PmsWorkLogs v-else-if="section==='work-logs'&&permitted('summary-view')"/><PmsTeamActivity v-else-if="section==='team-activity'&&permitted('time-tracking-dashboard')"/><PmsMyWork :user-id="userId" v-else-if="section==='my-work'&&permitted('my-work-view')" :csrf="csrf" :permissions="permissions"/><PmsWorkflows v-else-if="section==='workflows'&&permitted('department-view')" :csrf="csrf" :permissions="permissions"/><PmsEmployees v-else-if="section==='employees'&&permitted('employee-view')" :csrf="csrf" :permissions="permissions"/><PmsProjects :key="'project-'+navigationVersion" :initial-project="selectedProject" :create-department="createDepartment" v-else-if="section==='projects'&&permitted('project-view')" :csrf="csrf" :permissions="permissions"/><template v-else-if="['departments','roles'].includes(section)&&permitted(key+'-view')"><PmsFormDialog v-if="editor" wide :centered="true" :title="section==='departments'?(editor.id?'Edit department':'Create department'):(editor.id?'Edit role':'Create role')" :subtitle="section==='departments'?'Add a department for employees and project workflows.':undefined" @close="editor=null"><form class="pms-reference-form" @submit.prevent="save"><template v-if="section==='departments'"><label>Name <span class="text-danger">*</span><input placeholder="Enter Name" v-model="editor.dept_name" required maxlength="255"></label><label>Status<select v-model.number="editor.status"><option :value="1">Active</option><option :value="0">Inactive</option></select></label><label class="full-width">Description<textarea v-model="editor.description" required rows="3" placeholder="Enter Description here..."></textarea></label></template><template v-else><label>Role name<input v-model="editor.role_name" required maxlength="255"></label><label>Role key<input v-model="editor.role_key" required maxlength="255" pattern="[a-zA-Z0-9_-]+"></label><fieldset class="pms-permission-grid pms-role-permission-editor"><legend>Permissions ({{editor.permission_ids.length}} selected)</legend><label class="full-width">Find permissions<input v-model="permissionSearch" type="search" placeholder="Search permissions..."></label><div class="editor-actions full-width"><button type="button" class="button" @click="editor.permission_ids=catalog.map(p=>p.id)">Select all</button><button type="button" class="button" @click="editor.permission_ids=[]">Clear</button></div><label v-for="p in visiblePermissions" :key="p.id" class="check"><input type="checkbox" v-model="editor.permission_ids" :value="p.id"><span>{{p.permission_name}}<small class="text-muted">{{p.permission_key}}</small></span></label></fieldset></template><div class="editor-actions"><button class="button primary" :disabled="busy">{{busy?'Saving...':'Save'}}</button><button type="button" class="button" @click="editor=null">Cancel</button></div></form></PmsFormDialog><template v-if="loading" role="status"></template><div v-else class="pms-table-card" :class="{'pms-department-list':section==='departments'}"><div class="pms-table-heading"><button v-if="section==='roles'&&permitted('permission-view')" class="button" @click="change('permissions')">Permission catalogue</button><button v-if="permitted(key+'-add')" class="button primary" @click="edit()"><i aria-hidden="true" class="ti ti-circle-plus"></i>Create</button></div><PmsTableControls :total="filteredRows.length" v-model:page="tablePage" v-model:size="tableSize" v-model:search="tableSearch"/><table class="pms-table"><thead><tr><th scope="col">ID</th><th scope="col">{{section==='departments'?'Name':'Role'}}</th><th scope="col">{{section==='departments'?'Description':'Role key'}}</th><th scope="col">{{section==='departments'?'Status':'Permissions'}}</th><th scope="col">Actions</th></tr></thead><tbody><tr v-for="row in pagedRows" :key="row.id"><td>{{row.id}}</td><td>{{row.dept_name||row.role_name}}</td><td>{{section==='departments'?row.description:row.role_key}}</td><td><span v-if="section==='departments'" class="badge" :class="Number(row.status)===1?'bg-label-success':'bg-label-danger'">{{Number(row.status)===1?'Active':'Inactive'}}</span><button v-else class="pms-role-permission-summary" @click="rolePreview=row"><i class="ti ti-shield-check" aria-hidden="true"></i>{{row.permissions?.length||0}} permissions<span>View</span></button></td><td><div class="row-actions"><button class="pms-icon-action btn btn-sm btn-icon text-primary" aria-label="Edit record" v-if="permitted(key+'-edit')" @click="edit(row)"><i class="ti ti-edit"></i></button><button class="pms-icon-action btn btn-sm btn-icon text-danger" aria-label="Delete record" v-if="permitted(key+'-trash')" :disabled="busy" @click="remove(row)"><i class="ti ti-trash"></i></button></div></td></tr><tr v-if="!rows.length"><td colspan="5">No records found.</td></tr></tbody></table><PmsTableControls footer :total="filteredRows.length" v-model:page="tablePage" v-model:size="tableSize"/></div></template><p v-else-if="permissions.length" class="muted">Your account has no department or role administration permission.</p></template></main></div></section></template>
